//! Renders a validated [`VersionPalette`](super::model::VersionPalette) to the Rust
//! source `bedrock_vanilla_data` compiles.
//!
//! Every list on the model is already sorted (`model.rs`), so emission just walks it in
//! order -- the stable-ordering half of the determinism requirement is earned before this
//! module runs, not here.

use proc_macro2::TokenStream;
use quote::quote;

use super::model::{BlockSpec, PropertyKind, PropertySpec, VersionPalette};

/// The generated file's module name for one version, e.g. `v1_20_10` for `(1, 20, 10)`.
pub fn module_name(game_version: (u8, u8, u8)) -> String {
    let (major, minor, patch) = game_version;
    format!("v{major}_{minor}_{patch}")
}

/// Renders one version's palette to a full source file (including the `#![doc]` file
/// header and the `use` it needs), ready to hand to `prettyplease`.
///
/// The header is built as an explicit `#![doc = ...]` attribute with a pre-formatted
/// string, not a `//!` line comment: a `//!` comment is converted to its `#[doc]`
/// attribute by the compiler's lexer before `quote!` ever sees it, which happens too
/// early for `quote!`'s own `#var` interpolation to reach into its text.
pub fn render_version_file(palette: &VersionPalette) -> TokenStream {
    let tag = &palette.tag;
    let source_path = "metadata/vanilladata_modules/mojang-blocks.json";
    let (major, minor, patch) = palette.game_version;

    let header = format!(
        " Generated by `cargo xtask generate-palette` from the `{tag}` release of \
          `Mojang/bedrock-samples`, path `{source_path}`. Do not edit by hand -- edit \
          the generator (`xtask/src/codegen/palette`) or the pinned dump \
          (`xtask/dumps/bedrock-samples`) instead, and regenerate."
    );

    let properties = palette.properties.iter().map(render_property_spec);
    let blocks = palette.blocks.iter().map(render_block_spec);

    quote! {
        #![doc = #header]

        use crate::palette::{BlockSpec, PropertyKind, PropertySpec, VersionPalette};

        pub static PALETTE: VersionPalette = VersionPalette {
            tag: #tag,
            game_version: (#major, #minor, #patch),
            properties: &[
                #(#properties),*
            ],
            blocks: &[
                #(#blocks),*
            ],
        };
    }
}

/// Renders the top-level `generated/mod.rs`: one `pub mod` per version plus the
/// `PALETTES` registry, oldest version first (the same order [`VersionPalette`]s were
/// handed in, which the caller is responsible for sorting -- see `mod.rs`).
pub fn render_mod_file(module_names: &[String]) -> TokenStream {
    let mods = module_names.iter().map(|m| {
        let ident = syn::Ident::new(m, proc_macro2::Span::call_site());
        quote! { pub mod #ident; }
    });
    let entries = module_names.iter().map(|m| {
        let ident = syn::Ident::new(m, proc_macro2::Span::call_site());
        quote! { #ident::PALETTE }
    });

    quote! {
        //! Generated by `cargo xtask generate-palette`. Do not edit by hand.

        #(#mods)*

        /// Every generated per-version palette, oldest game version first.
        pub static PALETTES: &[crate::palette::VersionPalette] = &[
            #(#entries),*
        ];
    }
}

fn render_property_spec(spec: &PropertySpec) -> TokenStream {
    let name = &spec.name;
    let kind = match &spec.kind {
        PropertyKind::Bool => quote! { PropertyKind::Bool },
        PropertyKind::Int(values) => quote! { PropertyKind::Int(&[#(#values),*]) },
        PropertyKind::Str(values) => quote! { PropertyKind::Str(&[#(#values),*]) },
    };
    quote! {
        PropertySpec {
            name: #name,
            kind: #kind,
        }
    }
}

fn render_block_spec(spec: &BlockSpec) -> TokenStream {
    let name = &spec.name;
    let properties = &spec.properties;
    quote! {
        BlockSpec {
            name: #name,
            properties: &[#(#properties),*],
        }
    }
}
